import httpx
import time

class RetryClient(httpx.Client):
    def __init__(self, max_retries: int = 3, backoff_factor: float = 1.0, **kwargs):
        super().__init__(**kwargs)
        self.max_retries = max_retries
        self.backoff_factor = backoff_factor

    def request(self, method, url, **kwargs):
        for attempt in range(self.max_retries):
            try:
                return super().request(method, url, **kwargs)
            except (httpx.ConnectError, httpx.TimeoutException, httpx.PoolTimeout) as e:
                if attempt < self.max_retries - 1:
                    wait_time = self.backoff_factor * (2 ** attempt)
                    time.sleep(wait_time)
                else:
                    raise

if __name__ == "__main__":
    client = RetryClient(max_retries=3, backoff_factor=0.5)

    try:
        response = client.get("https://httpbin.org/status/200", timeout=10.0)
        print(f"Status: {response.status_code}")
    except httpx.HTTPError as e:
        print(f"Request failed after retries: {e}")
